namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Controllers")]
    [TestClass]
    public class RJIT_CR_API_C_00017 : ControllerTestBase
    {
        [TestMethod]
        public void Should_Not_Have_Nested_Or_Multiple_Classes()
        {
            var nestedOrMultipleClasses = (from syntaxTree in AllSyntaxTrees
                                           from @class in syntaxTree.Classes
                                           where @class.BaseTypes.Any(baseType => baseType.TypeName == "ControllerBase") && syntaxTree.Classes.Count > 1
                                           select new
                                           {
                                               File = syntaxTree.FileName, 
                                               MultipleClasses = syntaxTree.Classes.Select(c => c.Name).Flatten(";")
                                           }).ToImmutableList();


            Assert.IsTrue(nestedOrMultipleClasses.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00017

Only one controller have to be defined in one code file: {Environment.NewLine}{ConsoleTable.From(nestedOrMultipleClasses)}");
        }
    }
